create table if not exists public.product_search_synonyms(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,term text not null,synonyms text[] not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,term));
create table if not exists public.product_search_ranking_rules(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,boost numeric not null default 0 check(boost between -100 and 100),pinned boolean not null default false,active boolean not null default true,starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,product_id));
alter table public.product_search_synonyms enable row level security;alter table public.product_search_ranking_rules enable row level security;
create policy search_synonyms_admin on public.product_search_synonyms for all to authenticated using(public.can_access_tenant(tenant_id,array['super_admin','admin']::public.role_key[]) or public.is_platform_staff(null)) with check(public.can_access_tenant(tenant_id,array['super_admin','admin']::public.role_key[]) or public.is_platform_staff(null));
create policy search_ranking_admin on public.product_search_ranking_rules for all to authenticated using(public.can_access_tenant(tenant_id,array['super_admin','admin']::public.role_key[]) or public.is_platform_staff(null)) with check(public.can_access_tenant(tenant_id,array['super_admin','admin']::public.role_key[]) or public.is_platform_staff(null));
create or replace function public.search_pro_dashboard(p_tenant uuid,p_days integer default 30) returns jsonb language plpgsql stable security definer set search_path=public as $$declare r jsonb;begin if not public.has_entitlement(p_tenant,'search.pro') then raise exception 'search_pro_required';end if;if not(public.can_access_tenant(p_tenant,array['super_admin','admin']::public.role_key[]) or public.is_platform_staff(null)) then raise exception 'forbidden';end if;select jsonb_build_object('searches',count(*),'zero_results',count(*) filter(where result_count=0),'zero_rate',case when count(*)=0 then 0 else round((count(*) filter(where result_count=0))::numeric*100/count(*),1) end,'top_queries',coalesce((select jsonb_agg(x) from(select query,count(*) searches,max(result_count) result_count from public.product_search_events where tenant_id=p_tenant and created_at>=now()-make_interval(days=>greatest(1,least(p_days,365))) group by query order by count(*) desc limit 10)x),'[]'::jsonb),'zero_queries',coalesce((select jsonb_agg(x) from(select query,count(*) searches from public.product_search_events where tenant_id=p_tenant and result_count=0 and created_at>=now()-make_interval(days=>greatest(1,least(p_days,365))) group by query order by count(*) desc limit 10)x),'[]'::jsonb)) into r from public.product_search_events where tenant_id=p_tenant and created_at>=now()-make_interval(days=>greatest(1,least(p_days,365)));return r;end$$;
create or replace function public.public_related_products(p_tenant uuid,p_product uuid,p_limit integer default 6) returns table(slug text,name text,cover_url text,price numeric,currency text) language plpgsql stable security definer set search_path=public as $$begin if not public.has_entitlement(p_tenant,'search.pro') then return;end if;return query select p.slug,p.name,(select ma.public_url from public.product_media pm join public.media_assets ma on ma.id=pm.media_id where pm.product_id=p.id order by pm.sort_order,pm.created_at limit 1),coalesce((select min(v.price) from public.product_variants v where v.product_id=p.id and v.status='active'),0),coalesce((select min(v.currency) from public.product_variants v where v.product_id=p.id and v.status='active'),'IRR') from public.products p where p.tenant_id=p_tenant and p.status='active' and p.id<>p_product and p.category_id=(select category_id from public.products where id=p_product and tenant_id=p_tenant) order by coalesce((select rr.pinned::int*1000+rr.boost from public.product_search_ranking_rules rr where rr.tenant_id=p_tenant and rr.product_id=p.id and rr.active and (rr.starts_at is null or rr.starts_at<=now()) and (rr.ends_at is null or rr.ends_at>=now())),0) desc,p.created_at desc limit greatest(1,least(p_limit,12));end$$;
grant execute on function public.search_pro_dashboard(uuid,integer) to authenticated;grant execute on function public.public_related_products(uuid,uuid,integer) to anon,authenticated;
insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values('search.pro.analytics','تحلیل Search Pro','پرکاربردترین جستجوها و عبارت‌های بدون نتیجه را نشان می‌دهد تا مدیر بفهمد مشتری چه می‌خواهد و چه چیزی را پیدا نمی‌کند.','آمار فقط برای Tenant فعال و در صورت قرارداد Search Pro قابل مشاهده است.','Search Pro analytics','Shows top searches and zero-result queries so managers can understand demand and missed discovery opportunities.','Analytics are tenant-scoped and available only with Search Pro entitlement.',true),('search.pro.merchandising','Ranking و Synonym','مدیر می‌تواند مترادف‌های جستجو تعریف کند و برای محصولات Boost یا Pin تعیین کند تا ترتیب نتایج تجاری قابل کنترل باشد.','قوانین نباید محصولات غیرفعال یا متعلق به Tenant دیگر را قابل نمایش کنند.','Ranking and synonyms','Managers can define search synonyms and boost or pin products to control commercial ranking.','Rules must never expose inactive products or products belonging to another tenant.',true) on conflict(help_key) do update set title_fa=excluded.title_fa,body_fa=excluded.body_fa,warning_fa=excluded.warning_fa,title_en=excluded.title_en,body_en=excluded.body_en,warning_en=excluded.warning_en,active=true;